    local strCatEndCam = parse_string(row, "catEndCam", "")
    local arrayCatEnd = Tools.splitToNum(strCatEndCam, ',', ';')
    self.catEndCam = {
        position = Vector3.New(SafeUnpack(arrayCatEnd[1] or { 0, 0, 0 })),
        rotation = Quaternion.Euler(SafeUnpack(arrayCatEnd[2] or { 0, 0, 0 })) }

    local strCatEndLocation = parse_string(row, "catEnd", "")
