function BattleSceneVo:LoadPath(pathObj, isMine)
    local d = isMine and self.myPath or self.enemyPath
    local ds = Tools.splitToNum(d, ';', ',')
    
    print(table.toString(ds, "LoadPath"))
    pathObj.transform.position = Vector3.New(SafeUnpack(ds[1] or {0, 0, 0}))
    pathObj.transform.rotation = Quaternion.Euler(SafeUnpack(ds[2] or {0, 0, 0}))

    local csp = pathObj:GetComponent(typeof(CS.Cinemachine.CinemachineSmoothPath))
    local wps = {}
    for i=3, #ds do
        local wp = CS.Cinemachine.CinemachineSmoothPath.Waypoint()
        wp.position = Vector3.New(SafeUnpack(ds[i] or {0, 0, 0}))
        wp.roll = ds[i][4]
        table.insert(wps, wp)
    end
    csp.m_Waypoints = wps
end

